	out := make(chan int)
	var workers sync.WaitGroup
	for _, input := range inputs {
		workers.Add(1)
		go func(input <-chan int) {
			defer workers.Done()
			for value := range input {
				out <- value
			}
		}(input)
	}
	go func() { workers.Wait(); close(out) }()
	return out
}
