type Bucket struct {
	Capacity, Tokens, PerSecond float64
	Last                        time.Time
}

func (b *Bucket) Allow(now time.Time) bool {
	if now.Before(b.Last) {
		return false
	}
	b.Tokens = math.Min(b.Capacity, b.Tokens+now.Sub(b.Last).Seconds()*b.PerSecond)
	b.Last = now
	if b.Tokens < 1 {
		return false
	}
	b.Tokens--
	return true
}
